def _slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_") or "window"


def _titlebar_html(title: str, icon: str) -> str:
    return (
        '<div class="vista-titlebar">'
        f'<span class="vista-title"><span class="vista-icon">{icon}</span>{html.escape(title)}</span>'
        '<span class="vista-controls" aria-hidden="true">'
        '<span class="vista-ctl">&#8211;</span>'
        '<span class="vista-ctl">&#9633;</span>'
        '<span class="vista-ctl vista-close">&#10005;</span>'
        "</span></div>"
    )


@contextmanager
def vista_frame(title: str, icon: str = "🗔", key: str | None = None):

    key = key or _slug(title)
    with st.container(key=f"vwin_{key}"):
        st.markdown(_titlebar_html(title, icon), unsafe_allow_html=True)
        with st.container(key=f"vbody_{key}"):
            yield


def vista_window(title: str, content_fn, icon: str = "🗔", key: str | None = None):

    with vista_frame(title, icon, key):
        content_fn()


def vista_taskbar(pages, current: str):

    tasks = "".join(
        f'<span class="vista-task{" active" if p == current else ""}">'
        f'<span>{PAGE_ICONS.get(p, "🗔")}</span>'
        f'<span class="vista-task-label">{html.escape(p)}</span></span>'
        for p in pages
    )
    st.html(
        '<div class="vista-taskbar">'
        '<div class="vista-orb" title="Start"><span class="vista-flag"><i></i><i></i><i></i><i></i></span></div>'
        f'<div class="vista-tasks">{tasks}</div>'
        '<div class="vista-clock" id="vista-clock"></div>'
        "</div>"
        "<script>"
        "(function () {"
        "  function tick() {"
        "    var el = document.getElementById('vista-clock');"
        "    if (!el) return;"
        "    var d = new Date();"
        "    var date = document.createElement('small');"
        "    date.textContent = d.toLocaleDateString();"
        "    el.replaceChildren(d.toLocaleTimeString([], {hour: 'numeric', minute: '2-digit'}), date);"
        "  }"
        "  tick();"
        "  if (!window.__vistaClock) window.__vistaClock = setInterval(tick, 1000);"
        "})();"
        "</script>",
        unsafe_allow_javascript=True,
    )



@st.cache_data(show_spinner="Loading TikTok Shop videos…")
def load_midterm_data(source) -> tuple[pd.DataFrame, int]:

    if source == EMBEDDED:
        packed = "".join(MIDTERM_DATA_B85.split())
        source = io.BytesIO(lzma.decompress(base64.b85decode(packed)))
    raw = pd.read_csv(source, usecols=DATA_COLS)
    df = raw[raw["data_quality_flag"] == 1].drop(columns="data_quality_flag").dropna()
    df["log_views"] = np.log1p(df["video_views"])
    df["log_followers"] = np.log1p(df["creator_followers"])
    return df, len(raw)


@st.cache_data(show_spinner=False)
def clean_csv_bytes(source) -> bytes:

    return load_midterm_data(source)[0].to_csv(index=False).encode("utf-8")


@st.cache_resource(show_spinner="Fitting regression models…")
def fit_models(df: pd.DataFrame) -> dict:

    y = df["log_views"]
    X1_train, X1_test, y_train, y_test = train_test_split(
        df[["log_followers"]], y, test_size=0.2, random_state=42)
    model1 = LinearRegression().fit(X1_train, y_train)
    pred1 = model1.predict(X1_test)

    X2_train, X2_test, y2_train, y2_test = train_test_split(
        df[FEATS], y, test_size=0.2, random_state=42)
    model2 = LinearRegression().fit(X2_train, y2_train)
    pred2 = model2.predict(X2_test)

    results = pd.DataFrame({
        "Model": ["1: followers only", "2: + engagement, retention, hook, quality"],
        "R2": [r2_score(y_test, pred1), r2_score(y2_test, pred2)],
        "RMSE": [np.sqrt(mean_squared_error(y_test, pred1)),
                 np.sqrt(mean_squared_error(y2_test, pred2))],
        "MAE": [mean_absolute_error(y_test, pred1), mean_absolute_error(y2_test, pred2)],
    }).round(3)
    return {"model1": model1, "model2": model2, "results": results,
            "y2_test": y2_test, "pred2": pred2}


def hist_chart(values: pd.Series, title: str, x_title: str, bins: int = 50) -> alt.Chart:

    counts, edges = np.histogram(values, bins=bins)
    h = pd.DataFrame({"start": edges[:-1], "end": edges[1:], "count": counts})
    return alt.Chart(h, title=title).mark_bar(color="#3399FF").encode(
        x=alt.X("start:Q", bin="binned", title=x_title), x2="end",
        y=alt.Y("count:Q", title="Videos"))


def profile_markdown() -> str:

    lines = [f"# {NAME}", f"{PROGRAM} · {YEAR_LEVEL} · {SECTION}", SCHOOL, "", BIO, "",
             "## Projects"]
    lines += [f"- **{p['title']}** ({p['year']}, {p['role']}): {p['summary']}" for p in PROJECTS]
    lines += ["", "## Skills"] + [f"- {s}: {n} repos" for s, n in zip(SKILLS.Skill, SKILLS.Repos)]
    lines += ["", "## Links"] + [f"- {k}: {v}" for k, v in LINKS.items()]
    return "\n".join(lines)


